    "summary": "Savor a fusion of Japanese, Chinese, and Spanish cuisine at COYA Abu Dhabi",
    "description": "COYA is an upscale Peruvian fusion restaurant located near Emirates Palace, where you can experience the vibrant atmosphere of South America in Abu Dhabi. The menu impressively reinterprets authentic Peruvian dishes like ceviche, tiradito, and anticuchos with a modern twist, with seafood dishes being particularly outstanding. The lively atmosphere accompanied by Latin music is a highlight, and you must try the signature cocktail Pisco Sour crafted at the bar. With a review rating of 4.6, it's an excellent choice for special occasions, and on weekend nights, it transforms into a club atmosphere with DJ performances. If you're seeking a distinctive culinary experience, COYA comes highly recommended.",
