    "summary": "House of Artisans keeps vibrant traditions alive across generations",
    "description": "House of Artisans is a traditional crafts center nestled within Qasr Al Hosn, where you can discover and experience the UAE's time-honored handicrafts. Immerse yourself in workshops led by Emirati master craftspeople, learning Al Sadu (Bedouin weaving), Dallah (coffee pot) making, and Talli (golden thread embroidery), and take home your own handcrafted creation. Operating as part of the UAE's commitment to preserving intangible cultural heritage for modern generations, this center offers exceptional educational value. With a review score of 4.33, visitors respond enthusiastically to this unique experience. Visit alongside Qasr Al Hosn to gain profound insights into Emirati culture. If you love creating something with your own hands, this is an absolute must.",
