    "title": "Journey to the Beginning",
    "summary": "Discover royal heritage at Qasr Al Hosn",
    "description": "Qasr Al Hosn is Abu Dhabi's oldest stone building, constructed in the 1790s as the birthplace of the city and residence of its rulers throughout history. Evolving from its origins as a watchtower to its current fort structure, this building stands as a witness to UAE history, with interior exhibits chronicling Abu Dhabi's transformation through the ages. The surrounding area includes the Cultural Foundation, House of Artisans, and Bait Al Gahwa (Coffee House), offering a comprehensive Emirati cultural experience. With a review score of 4.6 reflecting high praise for its historical significance and exhibition content, this is an essential visit for anyone seeking to discover the history behind modern Abu Dhabi's glamour.",
