    "summary": "Scuba dive with over 330 species of marine life at the National Aquarium",
    "description": "At the National Aquarium, you can scuba dive among over 330 species of marine life in a thrilling experience that takes you swimming between sharks and rays. Even without certification, you can participate through discovery diving, where professional divers accompany you for a safe 30-minute underwater adventure. The experience includes a brief training session and comprehensive briefing beforehand, with underwater photo and video services available to capture your journey. Open to participants aged 10 and above, the aquarium also offers fun diving options for certified divers. As the UAE's safest venue for shark diving, this bucket-list experience promises memories that will last a lifetime.",
