    "summary": "Meet your favorite characters at Warner Bros. World",
    "description": "Warner Bros. World stands as the world's largest indoor theme park, where DC Comics superheroes unite with beloved characters from Looney Tunes and Hanna-Barbera under one spectacular roof. Six themed zones—including Gotham City, Metropolis, and Cartoon Junction—each perfectly recreate their unique universes with exceptional immersion. Despite being indoors, the soaring ceilings and brilliant lighting design eliminate any sense of confinement. Capture photos with Batman, Superman, and Wonder Woman, or relive childhood memories with Bugs Bunny, Tweety, and Tom and Jerry. Character dining experiences at themed restaurants add another layer of magic. With the entire park maintained in perfect air-conditioned comfort, even the height of summer becomes enjoyable, making this a beloved destination for all ages from children to adults.",
    "duration": "4-6hrs",
    "admission": "AED 315 (admission)",
    "hours": "10:00-20:00",
    "closed": "Open daily",
